const assetUrl = (value?: string) => {
  if (!value) return undefined;
  if (/^https?:\/\//.test(value)) return value;
  if (Platform.OS === "web") return value.startsWith("/") ? value : `/${value}`;
  const host = typeof window !== "undefined" && window.location.hostname ? window.location.hostname : "localhost";
  return `http://${host}:3329${value.startsWith("/") ? value : `/${value}`}`;
};
const progressFor = (payload: DetectiveCampaignPayload, caseId: string) => payload.progress?.find((item) => item.caseId === caseId);
const unlocked = (payload: DetectiveCampaignPayload, item: MobileCase) => !item.prerequisiteCaseId || progressFor(payload, item.prerequisiteCaseId)?.status === "solved";
const displayValue = (value: unknown) => typeof value === "object" && value && "label" in value && "value" in value ? `${String((value as any).label)}: ${String((value as any).value)}` : String(value ?? "");
