const localizeHandbook = (entry: any, isEnglish: boolean) => isEnglish && englishHandbookCopy[String(entry.id)] ? { ...entry, ...englishHandbookCopy[String(entry.id)] } : entry;

function evaluateCandidates(candidates: Array<Record<string, any>>, selected: string[], wrongAttempts: number) {
  const chosen = new Set(selected);
  const missing = candidates.filter((item) => item.isTrueCause && !chosen.has(String(item.id))).length;
  const traps = candidates.filter((item) => !item.isTrueCause && chosen.has(String(item.id))).length;
  const matched = candidates.filter((item) => Boolean(item.isTrueCause) === chosen.has(String(item.id))).length;
  if (selected.length > 0 && missing === 0 && traps === 0) {
    const stars = Math.max(0, 3 - wrongAttempts);
    return { isCorrect: true, stars, wrongAttempts, accuracy: 100, multiplier: stars === 3 ? 1 : stars === 2 ? 0.7 : stars === 1 ? 0.4 : 0.2, message: "Chính xác tuyệt đối! Bạn đã loại bỏ đúng các yếu tố gây nhiễu." };
  }
  const nextWrong = wrongAttempts + 1;
  return { isCorrect: false, stars: Math.max(0, 3 - nextWrong), wrongAttempts: nextWrong, accuracy: candidates.length ? Math.round(matched / candidates.length * 100) : 0, multiplier: nextWrong === 1 ? 0.7 : nextWrong === 2 ? 0.4 : 0.2, message: missing > 0 && traps > 0 ? "Hồ sơ còn thiếu nguyên nhân và đang chọn nhầm yếu tố gây nhiễu. Hãy rà lại Sổ Manh Mối và Sổ Tay Y Khoa." : missing > 0 ? "Hồ sơ vẫn còn thiếu nguyên nhân thực sự. Hãy kiểm tra lại các dữ kiện đã thu thập." : "Bạn đang chọn dư yếu tố gây nhiễu. Hãy đối chiếu lại bằng chứng." };
}

